      transform: translateX(-50%) translateY(100px);
      background: var(--velvet);
      border: 1px solid var(--border);
      padding: 0.75rem 1.5rem;
      border-radius: 4px;
      z-index: 2000;
      opacity: 0;
      transition: transform 0.3s ease, opacity 0.3s ease;
    }

    .toast.show {
      transform: translateX(-50%) translateY(0);
      opacity: 1;
    }

    /* Newsletter */
    .newsletter {
      max-width: 1200px;
      margin: 4rem auto 0;
      padding: 0 1rem;
      text-align: center;
    }

    .newsletter-input {
      padding: 0.75rem 1.5rem;
      font-size: 1rem;
      background: var(--bg);
      border: 1px solid var(--border);
      border-radius: 4px;
      color: var(--ivory);
      width: 60%;
      max-width: 400px;
      margin: 0 auto 1rem;
    }

    .newsletter-input:focus {
      outline: none;
      border-color: var(--gold);
    }

    .newsletter-btn {
      padding: 0.75rem 1.5rem;
      background: var(--gold);
      color: var(--bg);
      border: none;
      border-radius: 4px;
      font-size: 1rem;
      font-weight: 500;
      text-transform: uppercase;
      letter-spacing: 0.05em;
      cursor: pointer;
      transition: background 0.3s ease;
    }

    .newsletter-btn:hover {
      background: var(--soft-gold);
    }

    /* Footer */
    .footer {
      max-width: 1200px;
      margin: 4rem auto 0;
      padding: 2rem 1rem;
      text-align: center;
      border-top: 1px solid var(--border);
    }

    .footer .logo {
