      font-size: 0.75rem;
      margin-top: 1rem;
    }

    .footer .credits a {
      color: var(--gold);
      text-decoration: none;
    }

    /* Responsive */
    @media (max-width: 768px) {
      .nav-links {
        display: none;
        position: absolute;
        top: 100%;
        left: 0;
        width: 100%;
        background: var(--velvet);
