  <script>
    // Initialize current year
    document.getElementById('currentYear').textContent = new Date().getFullYear();

    // Color variables for JS
    const html = document.documentElement;

    // Smooth scroll for nav links
    document.querySelectorAll('a[href^="#"]').forEach(anchor => {
      anchor.addEventListener('click', function (e) {
        e.preventDefault();
        const target = document.querySelector(this.getAttribute('href'));
        if (target) {
          target.scrollIntoView({ behavior: 'smooth' });
        }
      });
    });

    // Active nav state while scrolling
    const sections = document.querySelectorAll('section[id]');
    const navLinks = document.querySelectorAll('.nav-links a');

    window.addEventListener('scroll', () => {
      let current = '';

      sections.forEach(section => {
        const sectionTop = section.offsetTop;
        const sectionHeight = section.clientHeight;
        if (pageYOffset >= sectionTop - 100) {
          current = section.getAttribute('id');
        }
      });

      navLinks.forEach(link => {
        link.classList.remove('active');
        if (link.getAttribute('href') === '#' + current) {
          link.classList.add('active');
        }
      });
    });

    // Mobile menu
    const mobileMenuBtn = document.getElementById('mobileMenuBtn');
    const navbarOverlay = document.getElementById('navbarOverlay');
    const navLinksMobile = document.getElementById('navLinks');

    mobileMenuBtn.addEventListener('click', () => {
      mobileMenuBtn.classList.toggle('open');
      navbarOverlay.classList.toggle('open');
      navLinksMobile.classList.toggle('active');
    });

    navbarOverlay.addEventListener('click', () => {
      mobileMenuBtn.classList.remove('open');
      navbarOverlay.classList.remove('open');
      navLinksMobile.classList.remove('active');
    });

    // Ticket tier selection
    function selectTier(button) {
      document.querySelectorAll('.ticket-tier').forEach(tier => {
        tier.classList.remove('selected', 'recommended');
      });
      button.classList.add('selected');

      // Add recommended badge to curator pass
      if (button.dataset.tier === 'curator') {
        button.classList.add('recommended');
      }
    }

    // Ticket modal
    function openTicketModal() {
      document.getElementById('ticketModal').classList.add('active');
    }

    function closeTicketModal() {
      document.getElementById('ticketModal').classList.remove('active');
      document.getElementById('ticketForm').reset();
      document.getElementById('successMessage').style.display = 'none';
    }

    // Close modal on ESC
    document.addEventListener('keydown', (e) => {
      if (e.key === 'Escape') {
        const modals = document.querySelectorAll('.modal.active');
        modals.forEach(modal => closeTicketModal());
        const artistModal = document.getElementById('artistModal');
        if (artistModal.classList.contains('active')) {
          closeArtistModal();
        }
      }
    });

    // Close modal on backdrop click
    document.getElementById('ticketModal').addEventListener('click', (e) => {
      if (e.target === e.currentTarget) {
        closeTicketModal();
      }
    });

    // FAQ accordion
    function toggleAccordion(question) {
      const item = question.parentElement;
      const answer = item.querySelector('.faq-answer');
      const arrow = question.querySelector('.faq-arrow');

      item.classList.toggle('open');
      answer.style.display = item.classList.contains('open') ? 'block' : 'none';
      arrow.textContent = item.classList.contains('open') ? '-' : '+';
    }

    // Initialize FAQ answers hidden
    document.querySelectorAll('.faq-answer').forEach(answer => {
      answer.style.display = 'none';
    });
    document.querySelectorAll('.faq-item')[0].classList.add('open');
    document.querySelectorAll('.faq-answer')[0].style.display = 'block';
    document.querySelectorAll('.faq-arrow')[0].textContent = '-';

    // Newsletter subscription
    function subscribeNewsletter() {
      const email = document.getElementById('newsletterEmail').value;
      const btn = event.target;

      if (email && email.includes('@')) {
        btn.textContent = 'Subscribed!';
        setTimeout(() => {
          btn.textContent = 'Subscribe';
          const toast = document.createElement('div');
          toast.className = 'toast';
          toast.textContent = 'Thank you for subscribing!';
          document.body.appendChild(toast);
          setTimeout(() => toast.remove(), 3000);
          document.getElementById('newsletterEmail').value = '';
        }, 1500);
      } else {
        showToast('Please enter a valid email address');
      }
    }

    function showToast(message) {
      const toast = document.createElement('div');
      toast.className = 'toast';
      toast.textContent = message;
      document.body.appendChild(toast);
      setTimeout(() => toast.remove(), 3000);
    }

    // .ics file generation for Save to Calendar
    function generateICS() {
      const startDate = new Date('2026-10-18T19:00:00');
      const endDate = new Date('2026-10-19T02:00:00');

